from qlib import Q
C='makeup-intro-hygiene'
Q(C,'basic',"메이크업의 기능으로 가장 거리가 먼 것은?","피부 질환을 치료하는 기능",[("얼굴의 단점을 보완하는 기능","단점을 가리고 장점을 살리는 것은 메이크업의 대표 기능입니다."),("자외선·먼지로부터 피부를 보호하는 기능","베이스 제품은 외부 자극을 막는 보호 기능이 있습니다."),("때와 장소에 맞는 이미지를 표현하는 기능","사회적·심리적 표현도 메이크업의 기능입니다.")],"메이크업 기능 = 보호·미적·심리적·사회적 (치료 X)","메이크업은 얼굴의 장점을 살리고 단점을 보완하는 **미적 기능**, 피부를 외부 자극에서 지키는 **보호 기능**, 자신감을 주는 **심리적 기능**, 때와 장소에 맞게 이미지를 나타내는 **사회적 기능**이 있습니다. 질병 치료는 의료의 영역입니다.",4,["메이크업 개념"],lock=True)
Q(C,'basic',"고대 이집트에서 눈 주위를 검게 칠하는 데 쓴 화장 재료는?","콜(kohl)",[("헤나","헤나는 손톱·머리카락을 물들이는 데 쓴 식물성 염료입니다."),("연지","연지는 볼과 입술을 붉게 칠하는 재료입니다."),("백분","백분은 얼굴을 희게 하는 가루분입니다.")],"고대 이집트 눈 화장 = 콜(kohl)","고대 이집트에서는 **콜(kohl)**이라는 검은 가루로 눈 주위를 길고 진하게 그렸습니다. 꾸미는 목적과 함께 강한 햇빛·벌레로부터 눈을 보호하는 목적도 있었다고 전해집니다.",3,["메이크업 역사"])
Q(C,'intermediate',"고려 시대 기생들을 중심으로 유행한, 분을 짙게 바르고 눈썹을 가늘게 그린 짙은 화장은?","분대화장",[("비분대화장","비분대화장은 엷고 자연스러운 화장을 뜻합니다."),("영육일치 화장","영육일치는 신라의 몸과 마음을 함께 가꾸는 사상입니다."),("담장","담장은 엷은 화장을 뜻하는 말입니다.")],"고려 기생의 짙은 화장 = 분대화장","고려 시대에는 기생을 중심으로 분을 하얗게 짙게 바르고 눈썹을 가늘고 또렷하게 그리며 머릿기름을 바르는 **분대화장**이 유행했습니다. 일반 여성은 엷은 화장(**비분대화장**)을 했습니다.",3,["메이크업 역사"])
Q(C,'intermediate',"1960년대 서양에서 유행한 메이크업의 특징으로 가장 알맞은 것은?","속눈썹을 길게 강조하고 아이라인을 뚜렷하게 그린 큰 눈 화장",[("가늘고 둥근 아치형 눈썹과 작고 진한 입술","이는 1920~30년대 화장의 특징입니다."),("굵고 자연스러운 눈썹을 살린 화장","굵은 자연 눈썹은 1980년대에 유행했습니다."),("창백한 피부와 검붉은 입술의 고딕 화장","이는 1960년대의 대표 특징이 아닙니다.")],"1960년대 = 큰 눈, 긴 속눈썹, 인형 같은 화장","1960년대에는 모델 트위기로 대표되는, 인조 속눈썹과 아이라인으로 **눈을 크고 또렷하게** 강조하고 입술은 옅게 표현한 화장이 유행했습니다.",3,["메이크업 역사"])
Q(C,'basic',"메이크업 작업장 위생 관리로 옳지 않은 것은?","여러 고객에게 쓴 퍼프를 세척 없이 그대로 다음 고객에게 쓴다",[("작업장을 자주 환기한다","환기는 작업장 위생 관리의 기본입니다."),("쓴 수건은 고객마다 새것으로 바꾼다","수건은 고객마다 교체합니다."),("쓰레기통은 뚜껑이 있는 것을 쓰고 자주 비운다","올바른 관리 방법입니다.")],"퍼프·스펀지는 고객마다 교체 또는 세척·소독","피부에 직접 닿는 퍼프·스펀지는 고객마다 새것을 쓰거나 세척·건조·소독한 것을 써야 합니다. 그대로 돌려 쓰면 세균·바이러스가 옮을 수 있습니다.",4,["작업장 위생"],lock=True)
Q(C,'basic',"립스틱을 여러 고객에게 위생적으로 쓰는 방법으로 가장 알맞은 것은?","스파출러로 덜어 내어 립 브러시로 바른다",[("립스틱을 고객 입술에 직접 바른다","직접 바르면 고객 사이에 균이 옮을 수 있습니다."),("작업자의 손가락으로 찍어 바른다","손가락은 위생적이지 않습니다."),("물티슈로 립스틱 표면만 닦고 직접 바른다","표면을 닦는 것만으로는 충분하지 않습니다.")],"공용 제품은 스파출러로 덜어 사용","크림·립스틱처럼 여러 사람이 쓰는 제품은 **스파출러**로 필요한 양만 덜어 팔레트에 옮긴 뒤 브러시로 바릅니다. 제품을 피부에 직접 대지 않는 것이 교차 감염을 막는 기본입니다.",5,["재료·도구 위생"])
Q(C,'intermediate',"천연모 메이크업 브러시를 세척한 뒤 말리는 방법으로 가장 알맞은 것은?","모양을 정리해 털이 아래로 향하거나 눕힌 상태로 그늘에서 말린다",[("털이 위로 향하게 컵에 세워 말린다","물이 손잡이 쪽으로 흘러 접착 부분이 상할 수 있습니다."),("드라이어의 뜨거운 바람으로 빨리 말린다","높은 열은 털을 상하게 합니다."),("직사광선이 강한 곳에서 말린다","직사광선은 털을 손상시킵니다.")],"브러시 = 털 아래로·눕혀서 그늘 건조","세척한 브러시는 모양을 다듬은 뒤 **털이 아래로 향하거나 눕힌 채** 통풍이 잘되는 그늘에서 말립니다. 털을 위로 세우면 물이 페럴(금속 부분) 안으로 스며 접착제가 약해집니다.",4,["재료·도구 위생"])
Q(C,'intermediate',"메이크업 작업자의 개인 위생 관리로 가장 알맞은 것은?","시술 전후에 손을 씻고 소독한다",[("손톱을 길게 길러 섬세한 작업에 쓴다","긴 손톱은 고객 피부를 다치게 하고 균이 남기 쉽습니다."),("향이 강한 향수를 넉넉히 뿌린다","강한 향은 고객에게 불쾌감을 줄 수 있습니다."),("감기 증상이 있어도 마스크 없이 시술한다","호흡기 감염을 옮길 수 있습니다.")],"작업자 위생 = 손 씻기·소독, 짧은 손톱","작업자는 **시술 전후 손을 씻고 소독**하며, 손톱은 짧게 다듬고, 깨끗한 복장을 갖춥니다. 감기 증상이 있으면 마스크를 써서 고객을 보호합니다.",4,["작업자 위생"])
Q(C,'basic',"고객 응대 절차에서 시술에 앞서 가장 먼저 해야 할 일은?","고객을 맞이하고 상담으로 원하는 이미지와 피부 상태를 확인한다",[("바로 베이스 메이크업을 시작한다","상담 없이 시작하면 고객의 요구와 피부 문제를 놓칩니다."),("시술 비용을 먼저 받고 끝낸다","비용 안내는 필요하지만 상담이 먼저입니다."),("작업자가 좋아하는 스타일로 정한다","고객의 요구를 먼저 들어야 합니다.")],"응대 순서: 맞이 → 상담 → 시술 → 마무리·배웅","고객 응대는 **맞이하기 → 상담(요구·피부 상태·알레르기 확인) → 시술 → 확인과 마무리 → 배웅** 순서로 이루어집니다. 상담 내용은 고객 관리 카드에 기록합니다.",4,["고객 응대"])
Q(C,'intermediate',"메이크업 고객 관리 카드에 적을 내용으로 가장 거리가 먼 것은?","고객 가족의 직업과 소득",[("피부 유형과 피부 트러블","시술에 필요한 정보입니다."),("화장품 알레르기 여부","부작용을 막기 위해 꼭 적습니다."),("사용한 제품과 시술 내용","다음 시술에 참고하기 위해 적습니다.")],"고객 카드 = 피부 상태·알레르기·시술 내용","고객 관리 카드에는 피부 유형, 트러블, **알레르기**, 원하는 이미지, 사용 제품과 시술 내용을 적습니다. 시술과 관계없는 개인정보는 모으지 않습니다.",3,["고객 관리"],lock=True)
Q(C,'advanced',"시술 중 고객이 눈이 따갑고 붉어졌다고 말할 때 작업자의 대처로 가장 알맞은 것은?","즉시 시술을 멈추고 제품을 제거한 뒤 깨끗한 물로 씻게 하고, 증상이 계속되면 병원 진료를 권한다",[("조금 참으면 괜찮아진다며 시술을 계속한다","자극이 계속되면 손상이 커질 수 있습니다."),("다른 색의 아이섀도로 덧발라 가린다","자극의 원인을 더하는 행동입니다."),("작업자가 가진 안약을 넣어 준다","의약품을 임의로 쓰는 것은 미용 업무가 아닙니다.")],"부작용 = 즉시 중단·제거·세척·진료 권유","시술 중 자극·알레르기 반응이 나타나면 **즉시 중단**하고 제품을 지운 뒤 깨끗한 물로 씻게 합니다. 증상이 계속되면 의사의 진료를 권하고 그 내용을 고객 카드에 기록합니다.",4,["고객 응대","안전"])
C='skin-science'
Q(C,'basic',"표피를 바깥쪽부터 순서대로 바르게 나열한 것은?","각질층 → 투명층 → 과립층 → 유극층 → 기저층",[("기저층 → 유극층 → 과립층 → 투명층 → 각질층","안쪽부터 나열한 순서입니다."),("각질층 → 과립층 → 투명층 → 유극층 → 기저층","투명층은 각질층 바로 아래에 있습니다."),("투명층 → 각질층 → 과립층 → 기저층 → 유극층","순서가 뒤섞여 있습니다.")],"표피(바깥→안): 각질-투명-과립-유극-기저","표피는 바깥부터 **각질층 → 투명층 → 과립층 → 유극층 → 기저층**입니다. 새 세포는 맨 아래 기저층에서 만들어져 위로 올라가 각질이 되어 떨어집니다. 투명층은 손바닥·발바닥에만 뚜렷합니다.",5,["피부 구조"])
Q(C,'intermediate',"피부색을 결정하는 멜라닌 색소를 만드는 세포가 있는 곳은?","표피의 기저층",[("표피의 각질층","각질층은 죽은 각질세포로 이루어집니다."),("진피의 망상층","진피에는 멜라닌 형성 세포가 없습니다."),("피하조직","피하조직은 지방이 주로 있는 층입니다.")],"멜라노사이트 = 기저층","멜라닌을 만드는 **멜라닌 형성 세포(멜라노사이트)**는 표피의 **기저층**에 있습니다. 자외선을 받으면 멜라닌이 늘어 피부를 보호하고, 지나치면 기미·주근깨가 생깁니다.",5,["피부 구조"])
Q(C,'basic',"피부의 탄력과 관계가 깊은 콜라겐과 엘라스틴이 주로 있는 층은?","진피",[("각질층","각질층은 표피의 맨 바깥층입니다."),("기저층","기저층은 새 세포를 만드는 표피의 층입니다."),("과립층","과립층은 표피의 중간층입니다.")],"탄력 섬유 = 진피의 콜라겐·엘라스틴","**진피**에는 **콜라겐**(교원섬유)과 **엘라스틴**(탄력섬유)이 있어 피부의 탄력과 힘을 유지합니다. 나이가 들면 이 섬유가 줄어 주름이 생깁니다.",5,["피부 구조"])
Q(C,'intermediate',"피지 분비가 많아 모공이 넓고 번들거리며 여드름이 생기기 쉬운 피부 유형은?","지성 피부",[("건성 피부","건성은 피지·수분이 부족해 당기고 각질이 일어납니다."),("중성 피부","중성은 유분과 수분이 균형을 이룬 피부입니다."),("민감성 피부","민감성은 자극에 쉽게 붉어지는 피부입니다.")],"지성 = 피지 많음, 모공 넓음, 번들거림","**지성 피부**는 피지 분비가 많아 모공이 넓고 번들거리며, 화장이 쉽게 지워지고 여드름이 생기기 쉽습니다. 메이크업 전에는 유분 조절 제품과 가벼운 베이스를 씁니다.",4,["피부 유형"])
Q(C,'intermediate',"자외선 중 파장이 가장 길어 진피까지 닿으며 색소 침착과 광노화의 주원인이 되는 것은?","UVA",[("UVB","UVB는 주로 표피에 닿아 홍반·화상을 일으킵니다."),("UVC","UVC는 대부분 오존층에서 흡수됩니다."),("적외선","적외선은 자외선이 아니라 열을 내는 광선입니다.")],"UVA = 장파장·진피·광노화 / UVB = 홍반·화상","**UVA**는 파장이 길어 **진피**까지 들어가 색소 침착과 **광노화**(주름·탄력 저하)를 일으킵니다. **UVB**는 홍반과 일광 화상의 주원인이며, 자외선 차단 지수 SPF 는 주로 UVB 차단 정도를 나타냅니다.",5,["피부와 광선"])
Q(C,'advanced',"피부와 영양에 대한 설명으로 옳지 않은 것은?","비타민 C 는 햇빛을 받으면 피부에서 만들어진다",[("비타민 A 가 부족하면 피부가 건조해지고 각질이 생기기 쉽다","옳은 설명입니다."),("비타민 C 는 콜라겐 합성을 돕고 멜라닌 생성을 억제한다","옳은 설명입니다."),("단백질은 피부 조직을 이루는 주요 성분이다","옳은 설명입니다.")],"햇빛으로 피부에서 만들어지는 것 = 비타민 D","자외선을 받으면 피부에서 만들어지는 것은 **비타민 D** 입니다. **비타민 C** 는 음식으로 섭취해야 하며 콜라겐 합성을 돕고 멜라닌 생성을 억제합니다.",4,["피부와 영양"],lock=True)
Q(C,'basic',"피부의 면역 기능을 맡아 외부에서 들어온 물질을 알아내는 세포로, 표피 유극층에 주로 있는 것은?","랑게르한스 세포",[("멜라닌 형성 세포","색소를 만드는 세포입니다."),("머켈 세포","촉각을 느끼는 데 관여하는 세포입니다."),("섬유아세포","진피에서 콜라겐을 만드는 세포입니다.")],"피부 면역 = 랑게르한스 세포(유극층)","**랑게르한스 세포**는 표피 유극층에 있는 면역 세포로, 피부에 들어온 이물질(항원)을 알아내 면역 반응을 일으킵니다.",4,["피부 면역"])
Q(C,'intermediate',"나이가 들며 생기는 피부 노화(내인성 노화)의 특징으로 알맞은 것은?","표피와 진피가 얇아지고 탄력이 떨어진다",[("피지 분비가 늘어 번들거린다","노화가 되면 피지 분비는 대체로 줄어듭니다."),("각질 교체 주기가 빨라진다","나이가 들면 교체 주기가 느려집니다."),("콜라겐이 늘어 피부가 두꺼워진다","콜라겐은 줄어듭니다.")],"내인성 노화 = 피부 얇아짐·탄력 저하","나이에 따른 **내인성 노화**에서는 피부가 얇아지고 콜라겐·엘라스틴이 줄어 **탄력이 떨어지며** 주름이 생깁니다. 피지와 땀 분비도 줄어 건조해집니다. 햇빛 때문에 생기는 **광노화**는 오히려 피부가 두껍고 거칠어지는 특징이 있습니다.",4,["피부 노화"])
Q(C,'advanced',"다음 중 바이러스에 의해 생기는 피부 질환은?","단순 포진",[("여드름","여드름은 피지·모공 막힘과 세균이 관여합니다."),("백선(무좀)","백선은 곰팡이(진균)가 원인입니다."),("기미","기미는 멜라닌 색소가 늘어난 색소 질환입니다.")],"바이러스 질환 = 단순 포진·사마귀·대상 포진","**단순 포진**(입술 주변 물집), 사마귀, 대상 포진은 **바이러스**가 원인입니다. 백선(무좀)·칸디다증은 **진균**, 농가진은 **세균**이 원인입니다. 감염성 질환이 있는 부위에는 메이크업을 하지 않습니다.",4,["피부 질환"])
Q(C,'basic',"땀샘 가운데 겨드랑이 등에 있어 사춘기 이후 활동하며 체취와 관계가 있는 것은?","아포크린샘(대한선)",[("에크린샘(소한선)","에크린샘은 온몸에 있어 체온을 조절하는 땀을 냅니다."),("피지선","피지선은 땀이 아니라 피지를 냅니다."),("림프샘","림프샘은 피부 부속기관이 아닙니다.")],"아포크린 = 겨드랑이·체취 / 에크린 = 온몸·체온 조절","**아포크린샘(대한선)**은 겨드랑이·유두 주변 등에 있고 사춘기 이후 활동하며, 땀이 세균에 분해되면 체취가 납니다. **에크린샘(소한선)**은 온몸에 퍼져 체온을 조절합니다.",3,["피부 부속기관"])
C='cosmetics'
Q(C,'basic',"화장품이 갖추어야 할 4대 요건이 아닌 것은?","치료성",[("안전성","피부에 해가 없어야 하는 요건입니다."),("안정성","보관 중 변질되지 않아야 하는 요건입니다."),("유효성","목적한 효과가 있어야 하는 요건입니다.")],"화장품 4대 요건 = 안전성·안정성·사용성·유효성","화장품의 4대 요건은 **안전성·안정성·사용성·유효성**입니다. 질병을 치료하는 것은 의약품의 목적입니다.",5,["화장품 기초"],lock=True)
Q(C,'intermediate',"물과 기름처럼 섞이지 않는 두 액체를 계면활성제로 섞어 크림·로션을 만드는 기술은?","유화",[("가용화","가용화는 적은 양의 기름을 물에 투명하게 녹이는 기술입니다."),("분산","분산은 안료 같은 가루를 액체에 고르게 퍼뜨리는 기술입니다."),("증류","증류는 끓는점 차이로 성분을 나누는 방법입니다.")],"크림·로션 = 유화 / 화장수 = 가용화 / 파운데이션 색 = 분산","**유화**는 물과 기름을 계면활성제로 섞어 우윳빛 크림·로션을 만드는 기술입니다. 화장수·향수처럼 투명한 제품은 **가용화**, 파운데이션·립스틱처럼 안료가 든 제품은 **분산** 기술을 씁니다.",5,["화장품 제조"])
Q(C,'intermediate',"계면활성제를 피부 자극이 적은 것부터 순서대로 나열한 것은?","비이온성 < 양쪽성 < 음이온성 < 양이온성",[("양이온성 < 음이온성 < 양쪽성 < 비이온성","자극이 큰 것부터 나열한 순서입니다."),("음이온성 < 비이온성 < 양쪽성 < 양이온성","비이온성이 가장 자극이 적습니다."),("양쪽성 < 양이온성 < 비이온성 < 음이온성","순서가 뒤섞여 있습니다.")],"자극: 양이온 > 음이온 > 양쪽성 > 비이온","계면활성제의 피부 자극은 일반적으로 **양이온성 > 음이온성 > 양쪽성 > 비이온성** 순서입니다. 비이온성은 자극이 적어 기초화장품에, 음이온성은 세정력이 좋아 클렌저에, 양이온성은 헤어 린스 등에 쓰입니다.",4,["화장품 원료"],lock=True)
Q(C,'basic',"피부에 수분을 끌어당겨 촉촉하게 유지해 주는 보습제 성분은?","글리세린",[("에탄올","에탄올은 청량감·수렴 효과를 주며 수분을 날려 보냅니다."),("파라벤","파라벤은 방부제입니다."),("이산화티타늄","이산화티타늄은 자외선을 반사하는 성분입니다.")],"보습제(습윤제) = 글리세린·히알루론산","**글리세린**은 공기 중 수분을 끌어당겨 피부를 촉촉하게 하는 대표적인 **보습제(습윤제)** 입니다. 히알루론산, 프로필렌글리콜도 보습 성분입니다.",4,["화장품 원료"])
Q(C,'intermediate',"자외선 차단 성분 가운데 자외선을 반사·산란시키는 물리적 차단제(무기 차단제)는?","징크옥사이드(산화아연)",[("옥틸메톡시신나메이트","자외선을 흡수하는 화학적 차단제입니다."),("벤조페논","자외선을 흡수하는 화학적 차단제입니다."),("글리세린","보습 성분입니다.")],"반사·산란 = 징크옥사이드·이산화티타늄","**징크옥사이드**와 **이산화티타늄**은 자외선을 **반사·산란**시키는 물리적 차단제로 자극이 적지만 하얗게 뜰 수 있습니다. 옥틸메톡시신나메이트·벤조페논은 자외선을 **흡수**하는 화학적 차단제입니다.",4,["기능성 화장품"])
Q(C,'advanced',"자외선 차단 지수(SPF)에 대한 설명으로 옳은 것은?","주로 UVB 를 막는 정도를 나타내며, 숫자가 클수록 차단 효과가 크다",[("UVA 를 막는 정도를 + 개수로 나타낸 것이다","UVA 차단 정도는 PA 로 나타냅니다."),("숫자가 작을수록 차단 효과가 크다","숫자가 클수록 효과가 큽니다."),("한 번 바르면 하루 종일 효과가 같다","땀·문지름으로 지워지므로 덧발라야 합니다.")],"SPF = UVB 차단, PA(+) = UVA 차단","**SPF** 는 주로 **UVB** 를 막는 정도이며 숫자가 클수록 차단 효과가 큽니다. **UVA** 차단 정도는 **PA+** ~ **PA++++** 처럼 + 개수로 나타냅니다.",5,["기능성 화장품"])
Q(C,'basic',"화장품의 미생물 오염을 막아 변질을 늦추기 위해 넣는 성분은?","방부제",[("보습제","보습제는 수분을 유지합니다."),("유연제","유연제는 피부를 부드럽게 합니다."),("착색제","착색제는 색을 냅니다.")],"변질 방지 = 방부제(파라벤 등)","**방부제**는 화장품 안에서 세균·곰팡이가 자라지 못하게 해 변질을 막습니다. 파라벤류, 페녹시에탄올 등이 쓰입니다.",4,["화장품 원료"])
Q(C,'intermediate',"향수를 부향률(향료 농도)이 높은 것부터 바르게 나열한 것은?","퍼퓸 > 오 드 퍼퓸 > 오 드 투알렛 > 오 드 코롱",[("오 드 코롱 > 오 드 투알렛 > 오 드 퍼퓸 > 퍼퓸","낮은 것부터 나열한 순서입니다."),("오 드 투알렛 > 퍼퓸 > 오 드 코롱 > 오 드 퍼퓸","순서가 뒤섞여 있습니다."),("오 드 퍼퓸 > 퍼퓸 > 오 드 코롱 > 오 드 투알렛","퍼퓸이 가장 진합니다.")],"부향률: 퍼퓸 > 오 드 퍼퓸 > 오 드 투알렛 > 오 드 코롱","향수는 부향률(향료 농도)에 따라 **퍼퓸 > 오 드 퍼퓸 > 오 드 투알렛 > 오 드 코롱** 순서로 진합니다. 진할수록 향이 오래 갑니다.",4,["화장품 종류"],lock=True)
Q(C,'advanced',"기능성 화장품의 효능에 해당하지 않는 것은?","여드름 등 피부 질환을 치료한다",[("피부의 미백에 도움을 준다","미백은 기능성 화장품의 효능입니다."),("피부의 주름 개선에 도움을 준다","주름 개선은 기능성 화장품의 효능입니다."),("자외선으로부터 피부를 보호한다","자외선 차단은 기능성 화장품의 효능입니다.")],"기능성 = 미백·주름 개선·자외선 차단 등 (치료 X)","기능성 화장품은 **미백, 주름 개선, 자외선 차단** 등에 도움을 주는 화장품입니다. 질병을 '치료'하는 것은 의약품의 영역이며, 화장품은 치료 효과를 내세울 수 없습니다. 다만 씻어 내는 제품으로 '여드름성 피부 완화'에 도움을 주는 것은 기능성 화장품에 들어갑니다.",4,["기능성 화장품"],lock=True)
